import { MakeLogicType, actions, kea, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { EightBallAnswerApi, askEightBall } from '../api'

// Long enough for one full shake, so a fast answer still gets its moment.
export const MIN_SHAKE_MS = 1200

function wait(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms))
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface magicEightBallLogicValues {
    askDisabledReason: string | null
    askError: string | null
    question: string
    result: EightBallAnswerApi | null
    resultLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface magicEightBallLogicActions {
    ask: () => any
    askFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    askSuccess: (
        result: EightBallAnswerApi,
        payload?: any
    ) => {
        result: EightBallAnswerApi
        payload?: any
    }
    setQuestion: (question: string) => {
        question: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface magicEightBallLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        askDisabledReason: (question: string, resultLoading: boolean) => string | null
    }
}

export type magicEightBallLogicType = MakeLogicType<
    magicEightBallLogicValues,
    magicEightBallLogicActions,
    Record<string, any>,
    magicEightBallLogicMeta
>

export const magicEightBallLogic = kea<magicEightBallLogicType>([
    path(['products', 'business_knowledge', 'frontend', 'scenes', 'magicEightBallLogic']),
    actions({
        setQuestion: (question: string) => ({ question }),
    }),
    loaders(({ values }) => ({
        result: [
            null as EightBallAnswerApi | null,
            {
                ask: async () => {
                    const [result] = await Promise.all([askEightBall(values.question.trim()), wait(MIN_SHAKE_MS)])
                    return result
                },
            },
        ],
    })),
    reducers({
        question: ['', { setQuestion: (_, { question }) => question }],
        askError: [
            null as string | null,
            {
                ask: () => null,
                askFailure: (_, { error }) => error,
            },
        ],
    }),
    selectors({
        askDisabledReason: [
            (s) => [s.question, s.resultLoading],
            (question: string, resultLoading: boolean): string | null => {
                if (resultLoading) {
                    return 'The ball is thinking'
                }
                if (!question.trim()) {
                    return 'Ask a product question first'
                }
                return null
            },
        ],
    }),
])
